import { LocationCollectionElementCloudPlatform } from './location-collection-element-cloud-platform';
import { LocationCollectionElementStage } from './location-collection-element-stage';
import { LocationCollectionElementStatus } from './location-collection-element-status';
import { LocationCollectionElementType } from './location-collection-element-type';
/**
 * A synthetic location.
 */
export interface LocationCollectionElement {
    cloudPlatform?: LocationCollectionElementCloudPlatform;
    /**
     * The Dynatrace entity ID of the location.
     */
    entityId: string;
    /**
     * Location's city.
     */
    geoCity?: string;
    /**
     * Location's continent.
     */
    geoContinent?: string;
    /**
     * Location's country.
     */
    geoCountry?: string;
    /**
     * Location's latitude.
     */
    geoLatitude?: number;
    /**
     * The Dynatrace GeoLocation ID of the location.
     */
    geoLocationId: string;
    /**
     * Location's longitude.
     */
    geoLongitude?: number;
    /**
     * The list of IP addresses assigned to the location.
     *
     *  Only applicable to `PUBLIC` locations.
     */
    ips?: string[];
    /**
     * The name of the location.
     */
    name: string;
    stage?: LocationCollectionElementStage;
    status?: LocationCollectionElementStatus;
    type: LocationCollectionElementType;
}
